import React, { createContext, useContext, useState, ReactNode } from 'react';
import { TRANSLATIONS } from './translations';
import { Language, TranslationStructure } from './types';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: TranslationStructure;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [language, setLanguage] = useState<Language>('es');

  const value = {
    language,
    setLanguage,
    t: TRANSLATIONS[language]
  };

  return (
    <LanguageContext.Provider value={value}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (context === undefined) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

import React, { useState, useEffect } from 'react';
import { useLanguage } from '../LanguageContext';
import { Language } from '../types';
import { Globe, Menu, X } from 'lucide-react';

export const Navbar: React.FC = () => {
  const { language, setLanguage, t } = useLanguage();
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const languages: { code: Language; label: string }[] = [
    { code: 'es', label: 'ES' },
    { code: 'en', label: 'EN' },
    { code: 'de', label: 'DE' },
    { code: 'fr', label: 'FR' },
    { code: 'se', label: 'SE' },
  ];

  const scrollToSection = (id: string) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
    setIsMobileMenuOpen(false);
  };

  return (
    <nav className={`fixed top-0 left-0 w-full z-50 transition-all duration-300 ${isScrolled ? 'bg-white text-brand-dark shadow-md py-3' : 'bg-transparent text-white py-6'}`}>
      <div className="container mx-auto px-6 flex justify-between items-center">
        {/* Logo */}
        <div className="text-xl font-serif font-bold tracking-widest cursor-pointer" onClick={() => window.scrollTo(0,0)}>
            CALA GAMBA <span className={`text-xs align-top ${isScrolled ? 'text-brand-gold' : 'text-brand-gold'}`}>11</span>
        </div>

        {/* Desktop Menu */}
        <div className="hidden md:flex items-center space-x-8 text-sm uppercase tracking-wide">
          <button onClick={() => scrollToSection('gallery')} className="hover:text-brand-gold transition-colors">{t.nav.photos}</button>
          <button onClick={() => scrollToSection('video')} className="hover:text-brand-gold transition-colors">{t.nav.video}</button>
          <button onClick={() => scrollToSection('location')} className="hover:text-brand-gold transition-colors">{t.nav.location}</button>

          <div className="relative group ml-4">
            <button className="flex items-center hover:text-brand-gold">
                <Globe className="w-4 h-4 mr-1" />
                <span>{language.toUpperCase()}</span>
            </button>
            <div className="absolute right-0 mt-2 w-24 bg-white rounded shadow-xl py-2 hidden group-hover:block text-brand-dark">
                {languages.map(lang => (
                    <button 
                        key={lang.code}
                        onClick={() => setLanguage(lang.code)}
                        className={`block w-full text-left px-4 py-2 hover:bg-stone-100 ${language === lang.code ? 'font-bold text-brand-gold' : ''}`}
                    >
                        {lang.label}
                    </button>
                ))}
            </div>
          </div>
        </div>

        {/* Mobile Toggle */}
        <button className="md:hidden" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
            {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="absolute top-full left-0 w-full bg-white text-brand-dark shadow-xl p-6 md:hidden flex flex-col space-y-4 text-center">
            <button onClick={() => scrollToSection('gallery')}>{t.nav.photos}</button>
            <button onClick={() => scrollToSection('video')}>{t.nav.video}</button>
            <button onClick={() => scrollToSection('location')}>{t.nav.location}</button>
            <div className="flex justify-center space-x-4 pt-4 border-t border-stone-100">
                {languages.map(lang => (
                    <button 
                        key={lang.code}
                        onClick={() => { setLanguage(lang.code); setIsMobileMenuOpen(false); }}
                        className={`p-2 ${language === lang.code ? 'text-brand-gold font-bold' : 'text-stone-400'}`}
                    >
                        {lang.label}
                    </button>
                ))}
            </div>
        </div>
      )}
    </nav>
  );
};

